// 작성자 송예찬
// [의사코드] 조명을 실제 크기로 반입하고 돔 안쪽 꼭대기에서 지지선으로 매단다.
// 기존 가운데 등만 숨기고 새 발광면 아래에 생활 공간을 향한 광원을 연결한다.
// [코딩]
using System;using System.IO;using System.Linq;using System.Collections.Generic;using UnityEngine;using UnityEngine.Rendering;using UnityEngine.Rendering.Universal;using UnityEditor;using UnityEditor.SceneManagement;using UnityEngine.SceneManagement;using Newtonsoft.Json;using Newtonsoft.Json.Linq;
public static class DomeLightWork {
 const string Root="Assets/Afrer_Seconds/";
 public static string W=>Path.GetFullPath(Path.Combine(Application.dataPath,"../../../tmp/DomeLight_20261103"));
 public static Transform[] All()=>SceneManager.GetActiveScene().GetRootGameObjects().SelectMany(g=>g.GetComponentsInChildren<Transform>(true)).ToArray();
 public static Transform Pod=>All().First(t=>t.name=="ObservationPod");
 static string P(Transform t)=>t.parent==null?t.name:P(t.parent)+"/"+t.name;
 static float[] V(Vector3 v)=>new[]{v.x,v.y,v.z};
 static Bounds B(GameObject g){var rr=g.GetComponentsInChildren<Renderer>(true).Where(r=>r.enabled&&r.gameObject.activeInHierarchy).ToArray();var b=rr[0].bounds;foreach(var r in rr.Skip(1))b.Encapsulate(r.bounds);return b;}
 static Material Existing(string name)=>AssetDatabase.LoadAssetAtPath<Material>(Root+"05.Model/Environment/B5/Materials/"+name+".mat");
 public static string Import(){var m=JObject.Parse(File.ReadAllText(Path.Combine(W,"model/manifest.json")));string target=Root+"05.Model/Environment/B5/DomePendantLight.fbx";File.Copy((string)m["fbx"],target,true);AssetDatabase.Refresh(ImportAssetOptions.ForceSynchronousImport);var importer=(ModelImporter)AssetImporter.GetAtPath(target);importer.materialImportMode=ModelImporterMaterialImportMode.ImportStandard;importer.materialLocation=ModelImporterMaterialLocation.InPrefab;importer.importAnimation=false;importer.importCameras=false;importer.importLights=false;importer.importNormals=ModelImporterNormals.Import;importer.importTangents=ModelImporterTangents.None;importer.addCollider=false;importer.SaveAndReimport();
 var go=new GameObject("DomePendantLight");var model=(GameObject)PrefabUtility.InstantiatePrefab(AssetDatabase.LoadAssetAtPath<GameObject>(target));model.transform.SetParent(go.transform,false);var materials=new Dictionary<string,Material>();foreach(var a in ((JObject)m["materials"]).Properties()){var c=a.Value;Material mat;if(a.Name.ToLower().Contains("white")||a.Name.ToLower().Contains("housing"))mat=Existing("OP_ClinicalWhite");else if(a.Name.ToLower().Contains("black")||a.Name.ToLower().Contains("dark")||a.Name.ToLower().Contains("metal")||a.Name.ToLower().Contains("cable"))mat=Existing("OP_BlackFrame");else if(a.Name.ToLower().Contains("steel"))mat=Existing("OP_BrushedSteel");else{string path=Root+"05.Model/Environment/B5/Materials/DomePendant_Diffuser.mat";mat=AssetDatabase.LoadAssetAtPath<Material>(path);if(!mat){mat=new Material(Shader.Find("Universal Render Pipeline/Lit"));mat.name="DomePendant_Diffuser";mat.SetColor("_BaseColor",new Color(.87f,.93f,.98f));mat.SetFloat("_Smoothness",.4f);mat.SetColor("_EmissionColor",new Color(.82f,.93f,1)*1.5f);mat.EnableKeyword("_EMISSION");AssetDatabase.CreateAsset(mat,path);}}if(!mat)throw new Exception("Material missing "+a.Name);materials[a.Name]=mat;}
 foreach(var r in go.GetComponentsInChildren<Renderer>()){r.sharedMaterials=r.sharedMaterials.Select(old=>materials[materials.Keys.First(k=>old.name.StartsWith(k))]).ToArray();r.shadowCastingMode=ShadowCastingMode.On;}
 var visualBounds=B(go);var expected=m["unitySizeXYZ"].ToObject<float[]>();if((visualBounds.size-new Vector3(expected[0],expected[1],expected[2])).magnitude>.002f)throw new Exception("Imported axes/bounds mismatch");string visualPrefab=Root+"05.Model/Environment/B5/DomePendantLight.prefab";PrefabUtility.SaveAsPrefabAsset(go,visualPrefab);
 var anchor=go.GetComponentsInChildren<Transform>(true).First(t=>t.name==(string)m["anchors"]["downwardLight"]["name"]);var source=new GameObject("Interior_Downlight");source.transform.SetParent(go.transform,false);source.transform.localPosition=go.transform.InverseTransformPoint(anchor.position)+Vector3.down*.015f;source.transform.localRotation=Quaternion.LookRotation(Vector3.down,Vector3.forward);var light=source.AddComponent<Light>();light.type=LightType.Spot;light.lightmapBakeType=LightmapBakeType.Realtime;light.color=new Color(.88f,.94f,1);light.intensity=7;light.range=8;light.spotAngle=82;light.innerSpotAngle=70;light.shadows=LightShadows.Soft;light.shadowResolution=LightShadowResolution.Low;light.shadowBias=.035f;light.shadowNormalBias=.15f;
 string functional=Root+"04.Prefabs/Environment/DomePendantLight.prefab";PrefabUtility.SaveAsPrefabAsset(go,functional);UnityEngine.Object.DestroyImmediate(go);m["modelAssetPath"]=target;m["visualPrefab"]=visualPrefab;m["functionalPrefab"]=functional;File.WriteAllText(Root+"06.Data/AssetSources/DomePendantLight_source_manifest.json",m.ToString());AssetDatabase.SaveAssets();return "Pendant visual and functional light prefab imported";}
 public static string Apply(){if(EditorApplication.isPlaying||!SceneManager.GetActiveScene().path.EndsWith("Level_B5_Isolation.unity"))throw new Exception("B5 edit mode required");if(Pod.Find("Dome_InteriorPendant"))throw new Exception("Already applied");Physics.SyncTransforms();var center=Pod.position;var ray=new Ray(new Vector3(center.x+.05f,center.y+2,center.z+.05f),Vector3.up);var hits=Physics.RaycastAll(ray,8).Where(h=>h.transform.IsChildOf(Pod)&&h.collider.enabled).OrderBy(h=>h.distance).ToArray();if(hits.Length==0)throw new Exception("No dome inner roof hit");float innerRoof=hits[0].point.y;var old=All().First(t=>t.name=="Cell_Lamp"&&P(t).Contains("Room01_Isolation"));foreach(var r in old.GetComponentsInChildren<Renderer>(true))r.enabled=false;foreach(var l in old.GetComponentsInChildren<Light>(true))l.enabled=false;
 var go=(GameObject)PrefabUtility.InstantiatePrefab(AssetDatabase.LoadAssetAtPath<GameObject>(Root+"04.Prefabs/Environment/DomePendantLight.prefab"),SceneManager.GetActiveScene());go.name="Dome_InteriorPendant";go.transform.SetPositionAndRotation(new Vector3(center.x,innerRoof-.034f,center.z),Quaternion.identity);go.transform.SetParent(Pod,true);var b=B(go);var light=go.GetComponentInChildren<Light>();if(b.max.y>innerRoof+.01f||b.min.y<center.y+3)throw new Exception("Pendant clearance invalid");
 var clone=UnityEngine.Object.Instantiate(Pod.gameObject);clone.name="ObservationPod_Habitat";clone.transform.SetPositionAndRotation(Vector3.zero,Quaternion.identity);PrefabUtility.SaveAsPrefabAsset(clone,Root+"04.Prefabs/Environment/ObservationPod_Habitat.prefab");UnityEngine.Object.DestroyImmediate(clone);EditorSceneManager.MarkSceneDirty(SceneManager.GetActiveScene());EditorSceneManager.SaveScene(SceneManager.GetActiveScene());AssetDatabase.SaveAssets();File.WriteAllText(Path.Combine(W,"placement.json"),JsonConvert.SerializeObject(new{scene=SceneManager.GetActiveScene().path,podPosition=V(Pod.position),podScale=V(Pod.localScale),innerRoof=innerRoof,mountPosition=V(go.transform.position),fixtureBoundsCenter=V(b.center),fixtureBoundsSize=V(b.size),fixtureBottom=b.min.y,fixtureTop=b.max.y,lightPosition=V(light.transform.position),direction=V(light.transform.forward),intensity=light.intensity,range=light.range,spotAngle=light.spotAngle,oldLampDisabled=old.GetComponentsInChildren<Light>(true).All(l=>!l.enabled)&&old.GetComponentsInChildren<Renderer>(true).All(r=>!r.enabled),colliders=go.GetComponentsInChildren<Collider>().Length},Formatting.Indented));return "Center pendant mounted inside the dome with existing fixture preserved disabled";}
 public static void Render(string file,Vector3 pos,Vector3 target){var hidden=All().SelectMany(t=>t.GetComponents<CharacterController>()).SelectMany(c=>c.GetComponentsInChildren<Renderer>(true)).Where(r=>r.enabled).ToArray();foreach(var r in hidden)r.enabled=false;var g=new GameObject("Temporary_LightReviewCamera");g.hideFlags=HideFlags.HideAndDontSave;var c=g.AddComponent<Camera>();c.enabled=false;c.transform.SetPositionAndRotation(pos,Quaternion.LookRotation(target-pos));c.fieldOfView=65;c.nearClipPlane=.04f;c.farClipPlane=80;c.useOcclusionCulling=false;c.allowHDR=true;c.GetUniversalAdditionalCameraData().renderPostProcessing=true;var rt=new RenderTexture(1600,1000,24);var previous=RenderTexture.active;try{c.targetTexture=rt;c.Render();c.Render();c.Render();RenderTexture.active=rt;var image=new Texture2D(1600,1000,TextureFormat.RGB24,false);image.ReadPixels(new Rect(0,0,1600,1000),0,0);image.Apply();File.WriteAllBytes(Path.Combine(W,file),image.EncodeToPNG());UnityEngine.Object.DestroyImmediate(image);}finally{c.targetTexture=null;RenderTexture.active=previous;rt.Release();UnityEngine.Object.DestroyImmediate(rt);UnityEngine.Object.DestroyImmediate(g);foreach(var r in hidden)r.enabled=true;}}
 public static string Before()=>Photos("before"); public static string After()=>Photos("after"); public static string Photos(string phase){var center=Pod.position;Render(phase+"_exterior.png",center+new Vector3(5.1f,3.8f,-6),center+new Vector3(0,3.1f,0));Render(phase+"_interior.png",center+new Vector3(.4f,1.95f,1),center+new Vector3(0,4.5f,-.5f));return "Light review photos captured";}
}
